/* walkthroughs.mjs — "งาน" ทีละขั้นตอนของคู่มือฉบับละเอียดแยกบทบาท
   แต่ละงาน (task) = ลำดับขั้น (steps) ที่รันต่อเนื่องบนหน้าเดียวกันใน Chromium (capture-steps.mjs):
     start: { as, vp|tall }             ผู้ใช้ที่ล็อกอิน + ขนาดหน้าจอของงานนี้
     step: { title, text, do(p, h), marks:[{sel,label,desc}], fields:[[ชื่อช่อง, คำอธิบาย]], result, note, warn,
             tall|crop|vp, shot:false (ขั้นที่ไม่มีภาพ), as (สลับผู้ใช้กลางงาน) }
   sel ใช้ selector ของ Playwright ได้เต็มรูปแบบ (เช่น .card:has(.card-head-title:text-is("…")), text=…)
   ในข้อความใช้ (1) (2) … อ้างหมายเลขวงกลมบนภาพ ตามลำดับ marks */

const URL = 'https://saeduflow.edu.chula.ac.th';
const MENU = n => `#sidebar .nav-it:has-text("${n}")`;
const CARD = t => `.card:has(.card-head-title:text-is("${t}"))`;
const BTN = t => `button:has-text("${t}")`;
const TOP = { sidebar: { sel: '#sidebar .app-side-nav', label: 'เมนูหลัก', desc: 'สลับหน้าต่าง ๆ ของระบบ ตัวเลขสีแดง = จำนวนงานที่รอ' }, bell: { sel: '#notif-btn', label: 'กระดิ่งแจ้งเตือน', desc: 'จำนวนงานที่ถึงคิวคุณ และทางเข้าเชื่อม LINE' }, user: { sel: '#sidebar [data-action="logout"]', label: 'ออกจากระบบ', desc: 'ปุ่มมุมล่างซ้าย ข้างชื่อผู้ใช้' } };

